{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.line = 0
  }
}

const fail = (m) => {
  throw new ParseError(m)
}

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const INT = '[+-]?\\d+(?:_\\d+)*'
const intRe = new RegExp(`^${INT}$`)
const floatRe = new RegExp(`^${INT}(?:\\.\\d+(?:_\\d+)*(?:[eE][+-]?\\d+(?:_\\d+)*)?|[eE][+-]?\\d+(?:_\\d+)*)$`)

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  peek() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  // at end of line or at a comment (after whitespace skipped)
  atEnd() {
    return this.i >= this.s.length || isComment(this.s[this.i])
  }
}

function parseString(L) {
  const q = L.s[L.i++]
  let out = ''
  if (q === "'") {
    const j = L.s.indexOf("'", L.i)
    if (j < 0) fail('unterminated string')
    out = L.s.slice(L.i, j)
    L.i = j + 1
    return out
  }
  for (;;) {
    const c = L.s[L.i]
    if (c === undefined) fail('unterminated string')
    L.i++
    if (c === '"') return out
    if (c !== '\\') {
      out += c
      continue
    }
    const e = L.s[L.i]
    if (e === undefined) fail('unterminated string')
    // take a whole code point for the message
    const ch = String.fromCodePoint(L.s.codePointAt(L.i))
    L.i += ch.length
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.slice(L.i, L.i + 4)
      if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else fail('invalid escape \\' + ch)
  }
}

function parseName(L) {
  const c = L.peek()
  if (c === '"' || c === "'") return parseString(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.s[L.i])) L.i++
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const names = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.peek() === '.') {
      L.i++
      L.ws()
      names.push(parseName(L))
    } else {
      L.i = save
      return names
    }
  }
}

function parseValue(L, path) {
  const c = L.peek()
  if (c === undefined || isComment(c) && false) fail('expected a value')
  if (c === '"') return { t: 'string', v: parseString(L) }
  if (c === "'") return { t: 'string', v: parseString(L) }
  if (c === '[') return parseArray(L, path)
  if (c === '{') return parseInline(L, path)
  const st = L.i
  while (L.i < L.s.length && !isWs(L.s[L.i]) && !',]}'.includes(L.s[L.i])) L.i++
  const tok = L.s.slice(st, L.i)
  if (tok === '' || isComment(tok[0]) && st === L.i) fail('expected a value')
  if (isComment(tok[0])) fail('expected a value')
  if (tok === 'true') return { t: 'boolean', v: true }
  if (tok === 'false') return { t: 'boolean', v: false }
  if (intRe.test(tok)) return { t: 'integer', v: Number(tok.replace(/_/g, '')) }
  if (floatRe.test(tok)) return { t: 'float', v: Number(tok.replace(/_/g, '')) }
  fail('invalid value ' + tok)
}

function parseArray(L, path) {
  L.i++
  const items = []
  L.ws()
  if (L.peek() === ']') {
    L.i++
    return { t: 'array', items }
  }
  if (L.atEnd()) fail('unterminated array')
  for (;;) {
    L.ws()
    if (items.length > 0 && L.peek() === ']') {
      L.i++
      return { t: 'array', items }
    }
    items.push(parseValue(L, path))
    L.ws()
    const c = L.peek()
    if (c === ',') {
      L.i++
      continue
    }
    if (c === ']') {
      L.i++
      return { t: 'array', items }
    }
    fail('unterminated array')
  }
}

function parseInline(L, path) {
  L.i++
  const tbl = newTable()
  L.ws()
  if (L.peek() === '}') {
    L.i++
    return tbl
  }
  if (L.atEnd()) fail('unterminated inline table')
  for (;;) {
    L.ws()
    const names = parseDotted(L)
    L.ws()
    if (L.peek() !== '=') fail('expected = in an inline table')
    L.i++
    L.ws()
    const full = path.concat(names)
    const v = parseValue(L, full)
    assign(tbl, path, names, v)
    L.ws()
    const c = L.peek()
    if (c === ',') {
      L.i++
      continue
    }
    if (c === '}') {
      L.i++
      return tbl
    }
    fail('unterminated inline table')
  }
}

// Descend through `names` (all but the last) from `tbl`, creating tables.
function walk(tbl, base, names, count) {
  let cur = tbl
  for (let k = 0; k < count; k++) {
    let next = cur.map.get(names[k])
    if (next === undefined) {
      next = newTable()
      cur.map.set(names[k], next)
    } else if (next.t === 'aot') {
      next = next.items[next.items.length - 1]
    } else if (next.t !== 'table') {
      fail(base.concat(names.slice(0, k + 1)).join('.') + ' is not a table')
    }
    cur = next
  }
  return cur
}

function assign(tbl, base, names, value) {
  const cur = walk(tbl, base, names, names.length - 1)
  const last = names[names.length - 1]
  if (cur.map.has(last)) fail(`key ${base.concat(names).join('.')} is defined twice`)
  cur.map.set(last, value)
}

function parseHeader(L, root) {
  const isArr = L.s[L.i + 1] === '['
  L.i += isArr ? 2 : 1
  L.ws()
  const names = parseDotted(L)
  L.ws()
  const closeErr = () => fail('unterminated table header')
  if (L.peek() !== ']') closeErr()
  L.i++
  if (isArr) {
    if (L.peek() !== ']') closeErr()
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const parent = walk(root, [], names, names.length - 1)
  const last = names[names.length - 1]
  const full = names.join('.')
  const ex = parent.map.get(last)
  if (isArr) {
    if (ex === undefined) {
      const t = newTable()
      t.header = true
      parent.map.set(last, { t: 'aot', items: [t] })
      return t
    }
    if (ex.t !== 'aot') fail(full + ' is not an array of tables')
    const t = newTable()
    t.header = true
    ex.items.push(t)
    return t
  }
  if (ex === undefined) {
    const t = newTable()
    t.header = true
    parent.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(full + ' is not a table')
  if (ex.header) fail(`table ${full} is defined twice`)
  ex.header = true
  return ex
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  // curPath only used for error text on keys; recompute from headers
  lines.forEach((s, idx) => {
    try {
      const L = new Line(s)
      L.ws()
      if (L.i >= s.length || isComment(L.peek())) return
      if (L.peek() === '[') {
        const isArr = s[L.i + 1] === '['
        const start = L.i
        cur = parseHeader(L, root)
        // header path for error text
        const L2 = new Line(s)
        L2.i = start + (isArr ? 2 : 1)
        L2.ws()
        curPath = parseDotted(L2)
        return
      }
      const names = parseDotted(L)
      L.ws()
      if (L.peek() !== '=') fail('expected key = value')
      L.i++
      L.ws()
      const v = parseValue(L, curPath.concat(names))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.line = idx + 1
      throw e
    }
  })
  return root
}
"}

